def _normalize_url(url):
	# Plain-string normalization (no urllib — BPMN script tasks may not import
	# it). Strips scheme/www/trailing slash; unlike urlparse this does not
	# separate out query strings, so two URLs differing only by a tracking
	# param would not be caught as duplicates here — acceptable since every
	# source this pipeline creates lands as status=Pending for human review
	# anyway.
	if not url:
		return ""
	u = url.strip().lower()
	for prefix in ("https://", "http://"):
		if u.startswith(prefix):
			u = u[len(prefix):]
			break
	if u.startswith("www."):
		u = u[4:]
	return u.rstrip("/")


suggestions = (task_data.get("submit_source_suggestions_toolCallResult") or {}).get("suggestions") or []

existing_urls_docs = frappe.get_all("Threat Source", fields=["source_url"])
normalized_existing_urls = {
	_normalize_url(d.source_url) for d in existing_urls_docs if d.source_url
}

unique_sources = []
for suggestion in suggestions:
	source_url = (suggestion.get("url") or "").strip()
	if not source_url:
		continue
	normalized = _normalize_url(source_url)
	if normalized not in normalized_existing_urls:
		unique_sources.append({
			"source_name": suggestion.get("name"),
			"source_type": suggestion.get("type", "Other"),
			"source_url": source_url,
			"discovery_context": suggestion.get("reason"),
			"language": "English",
		})
		normalized_existing_urls.add(normalized)

result["extracted_sources"] = unique_sources
